import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../environments/environment';
import { Soporte } from '../models/soporte.model';

@Injectable({ providedIn: 'root' })
export class SoportesService {
  private apiUrl = `${environment.apiUrl}/soportes`;

  constructor(private http: HttpClient) {}

  getAll(): Observable<Soporte[]> {
    return this.http.get<Soporte[]>(this.apiUrl);
  }

  create(motivo: string): Observable<Soporte> {
    return this.http.post<Soporte>(this.apiUrl, { motivo });
  }

  update(id: number, data: Partial<Soporte>): Observable<Soporte> {
    return this.http.put<Soporte>(`${this.apiUrl}/${id}`, data);
  }

  delete(id: number): Observable<any> {
    return this.http.delete(`${this.apiUrl}/${id}`);
  }

  exportExcel(desde: string, hasta: string): Observable<Blob> {
    const params = new HttpParams().set('desde', desde).set('hasta', hasta);
    return this.http.get(`${this.apiUrl}/export/excel`, {
      params,
      responseType: 'blob',
    });
  }
}
